<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Bus,Crypt,DB,Http};
use Illuminate\Support\Str;
use App\Services\Social\SocialProtocol;
use App\Services\Marketing\MarketingAutomationTrigger;
use App\Jobs\AdvanceMarketingAutomation;
class MarketingAutomationTriggerTest extends TestCase {
 use RefreshDatabase;
 protected function setUp():void {parent::setUp();$this->artisan('migrate',['--path'=>'database/migrations/social','--force'=>true]);Http::preventStrayRequests();Bus::fake();$this->app->instance(\App\Support\AutomationResponseSupport::class,new class extends \App\Support\AutomationResponseSupport {public function available():bool{return true;}});config(['marketing.automation_cron_enabled'=>true]);DB::table('social_hub_settings')->insert(['id'=>1,'hub_url'=>'https://social.jwaistudio.online','client_id'=>'client-a','key_id'=>'key-a','encrypted_secret'=>Crypt::encryptString('fixture-secret'),'registered_domain'=>'a.example.com','enabled'=>true,'created_at'=>now(),'updated_at'=>now()]);}
 private function tick(array $data,array $h=[]){$path='/api/automation/tick';$body=json_encode($data);$h=$h?:SocialProtocol::headers('client-a','key-a','fixture-secret','hub-to-client','POST',$path,$body);return $this->call('POST',$path,[],[],[],array_merge(['CONTENT_TYPE'=>'application/json','HTTP_ACCEPT'=>'application/json'],collect($h)->mapWithKeys(fn($v,$k)=>['HTTP_'.strtoupper(str_replace('-','_',$k))=>$v])->all()),$body);}
 private function payload():array{return ['client_id'=>'client-a','registered_domain'=>'a.example.com','dispatch_id'=>(string)Str::uuid()];}
 public function test_signed_tick_is_durable_fast_and_duplicate_dispatch_does_not_repeat_work():void {$d=$this->payload();$this->tick($d)->assertOk()->assertJsonPath('status','accepted');$this->tick($d)->assertOk();$this->assertDatabaseCount('marketing_automation_triggers',1);Bus::assertDispatchedAfterResponse(AdvanceMarketingAutomation::class,1);Http::assertNothingSent();}
 public function test_wrong_signature_tenant_and_nonce_replay_are_blocked():void {$d=$this->payload();$h=SocialProtocol::headers('client-a','key-a','wrong','hub-to-client','POST','/api/automation/tick',json_encode($d));$this->tick($d,$h)->assertUnauthorized();$d['registered_domain']='other.example';$this->tick($d)->assertForbidden();$d=$this->payload();$h=SocialProtocol::headers('client-a','key-a','fixture-secret','hub-to-client','POST','/api/automation/tick',json_encode($d));$this->tick($d,$h)->assertOk();$this->tick($d,$h)->assertStatus(409);$this->assertDatabaseCount('marketing_automation_triggers',1);}
 public function test_unsupported_runtime_rejects_before_enqueue():void {$this->app->instance(\App\Support\AutomationResponseSupport::class,new class extends \App\Support\AutomationResponseSupport {public function available():bool{return false;}});$this->tick($this->payload())->assertOk()->assertJsonPath('reason','async_response_unavailable');$this->assertDatabaseCount('marketing_automation_triggers',0);Bus::assertNothingDispatched();}
 public function test_disabled_client_returns_signed_state_without_a_job():void {config(['marketing.automation_cron_enabled'=>false]);$this->tick($this->payload())->assertOk()->assertJsonPath('status','disabled')->assertHeader('X-Social-Response-Signature');Bus::assertNothingDispatched();$this->assertDatabaseCount('marketing_automation_triggers',0);}
 public function test_uninstalled_automation_tables_report_not_configured():void {\Illuminate\Support\Facades\Schema::drop('marketing_automation_triggers');$this->tick($this->payload())->assertOk()->assertJsonPath('status','not_configured');Bus::assertNothingDispatched();}
 public function test_client_advances_only_one_queued_trigger_and_never_reclaims_processing():void {$d=$this->payload();$this->tick($d)->assertOk();$calls=0;$this->app->instance(\App\Services\Marketing\MarketingAutomationRunner::class,new class($calls){public function __construct(public int &$calls){}public function tick($now):array {$this->calls++;return ['status'=>'idle'];}});$s=app(MarketingAutomationTrigger::class);$s->advanceOldest();$s->advanceOldest();$this->assertSame(1,$calls);$this->assertDatabaseHas('marketing_automation_triggers',['id'=>$d['dispatch_id'],'status'=>'finished']);Http::assertNothingSent();}
 public function test_later_pulse_recovers_queued_receipt_but_never_reclaims_processing():void {$a=$this->payload();$this->tick($a)->assertOk();DB::table('marketing_automation_triggers')->where('id',$a['dispatch_id'])->update(['created_at'=>now()->subMinute()]);$this->tick($this->payload())->assertOk();$calls=0;$this->app->instance(\App\Services\Marketing\MarketingAutomationRunner::class,new class($calls){public function __construct(public int &$calls){}public function tick($now):array {$this->calls++;return ['status'=>'idle'];}});app(MarketingAutomationTrigger::class)->advanceOldest();$this->assertDatabaseHas('marketing_automation_triggers',['id'=>$a['dispatch_id'],'status'=>'finished']);DB::table('marketing_automation_triggers')->where('status','queued')->update(['status'=>'processing']);app(MarketingAutomationTrigger::class)->advanceOldest();$this->assertSame(1,$calls);}
 public function test_key_rotation_blocks_previously_queued_work():void {$a=$this->payload();$this->tick($a)->assertOk();DB::table('social_hub_settings')->update(['key_id'=>'rotated']);app(MarketingAutomationTrigger::class)->advanceOldest();$row=DB::table('marketing_automation_triggers')->find($a['dispatch_id']);$this->assertSame('installation_changed',json_decode($row->result,true)['reason']);Http::assertNothingSent();}
}
